insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NZ:environmental-scientist','2026-08-11',null,47.84,99500,20,0,0,0,6,8,0,10,5,49,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 234313 Environmental Research Scientist, with Environmental Scientist as the alternative title.','shortage_note','Environmental Research Scientist 234313 is on the current Green List Tier 1; 20/20.','visa_basis','Tier 1 can support Straight to Residence when the specified Level 8+ environmental qualification and other current requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Environmental Scientist annual pay range NZD 72,000-127,000; 8/10.','entry_basis','Current Green List qualification conditions require NZQCF Level 8+ environmental study with specified credit/underpinning-degree conditions, so entry accessibility is deliberately conservative; 6/15.','entry_burden_basis','No universal statutory occupational registration applies to Environmental Scientists; 5/5.'),'2026-08-11'),
('NZ:agronomist','2026-08-11',null,49.28,102500,0,0,0,0,8,10,0,5,5,28,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','New Zealand ANZSCO 1.3 uses 234112 Agricultural Scientist with Agronomist as a specialisation. The later ANZSCO 2021 code 234115 is not promoted into the NZ 1.3 layer.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','Standard skilled-work treatment when a specific role meets current classification and immigration requirements; 5/10.','salary_method','Midpoint of Tahatū Soil and Plant Scientist annual pay range NZD 74,000-131,000, used as the closest transparent agronomy-aligned proxy; 10/10.','entry_basis','Relevant agricultural, soil, crop or plant-science tertiary study is normally expected for professional agronomy work; 8/15.','entry_burden_basis','No universal statutory occupational registration applies to Agronomists; 5/5.'),'2026-08-11'),
('NZ:farm-manager','2026-08-11',null,38.46,80000,0,0,0,0,15,6,0,3,5,29,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Broad Farmer and Farm Manager scope. The current Tier 2 Dairy Cattle Farmer 121313 pathway is a dairy-only subset and is not promoted to this canonical profile.','shortage_note','No generic Farm Manager Green List shortage credit is assigned; the dairy-only Tier 2 pathway is kept separate; 0/20.','visa_basis','A specific farm-management job must be classified by duties and sector; conservative generic-role credit 3/10.','salary_method','Midpoint of Tahatū current most-common Farmer and Farm Manager annual pay range NZD 56,000-104,000; 6/10.','entry_basis','Tahatū describes an experience-led route with agriculture, agribusiness and management study useful rather than one mandatory degree; 15/15.','entry_burden_basis','No single statutory professional register applies to generic Farm Managers; 5/5.'),'2026-08-11'),
('NZ:forestry-technician','2026-08-11',null,35.82,74500,0,0,0,0,15,6,0,5,5,31,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 1.3 occupation 311413 Life Science Technician includes Forestry Technical Officer and Forestry Technician specialisations.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','Standard skilled-work treatment when the role and applicant meet current requirements; 5/10.','salary_method','Midpoint of Tahatū current most-common Forest and Conservation Technician annual pay range NZD 57,000-92,000; 6/10.','entry_basis','Tahatū describes relevant forestry/environment study and practical experience with 0-3 years of training; 15/15.','entry_burden_basis','No universal statutory professional registration applies to Forestry Technicians; 5/5.'),'2026-08-11'),
('NZ:food-technologist','2026-08-11',null,44.95,93500,20,0,0,0,8,8,0,10,5,51,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 234212 Food Technologist is an exact canonical match.','shortage_note','Food Technologist 234212 is on the current Green List Tier 1; 20/20.','visa_basis','Tier 1 can support Straight to Residence when the listed food-technology/food-science qualification and other current requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Food Scientist and Technologist annual pay range NZD 69,000-118,000; 8/10.','entry_basis','Tahatū describes 3-5 years of training and the Green List requires specified Level 7+ food-related qualifications; 8/15.','entry_burden_basis','Food Technologist is not a universally statutorily registered profession; 5/5.'),'2026-08-11'),
('NZ:sustainability-specialist','2026-08-11',null,42.31,88000,0,0,0,0,10,8,0,3,5,26,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','The canonical Sustainability Specialist has no exact ANZSCO 1.3 occupation. NOL 132418 Chief Sustainability Officer is a senior executive classification and is not treated as equivalent.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','A specific role requires duty-based classification, so generic specialist visa credit is conservative at 3/10.','salary_method','Midpoint of Tahatū current most-common Sustainability Specialist annual pay range NZD 79,000-97,000; 8/10.','entry_basis','Relevant environmental, engineering, construction or related tertiary study is commonly expected; 10/15.','entry_burden_basis','No universal statutory occupational registration applies; optional professional credentials may be useful; 5/5.'),'2026-08-11'),
('NZ:horticulturist','2026-08-11',null,29.50,61360,0,0,0,0,15,4,0,3,5,27,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Generic Horticulturist spans nursery, crop-production, gardening and related work, so no single ANZSCO 1.3 code is forced into the canonical profile.','shortage_note','No generic Horticulturist Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','A specific horticulture role must be classified by its actual duties; conservative generic-role credit 3/10.','salary_method','Midpoint of Tahatū Nursery Grower most-common hourly pay NZD 24-35, annualised at 2,080 hours, used as the closest transparent horticulture proxy; 4/10.','entry_basis','Tahatū Nursery Grower describes 0-2 years of training with horticulture qualification or experience useful; 15/15.','entry_burden_basis','No universal statutory occupational registration applies to generic Horticulturists; 5/5.'),'2026-08-11'),
('NZ:animal-science-technician','2026-08-11',null,38.70,80500,0,0,0,0,12,6,0,5,5,28,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 1.3 occupation 311111 Agricultural Technician provides the animal-science/husbandry technical scope through specialisations including Artificial Insemination Technical Officer, Dairy Technician and Herd Tester. The later Australia-only 311113 Animal Husbandry Technician code is not forced into the NZ 1.3 layer.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned; 0/20.','visa_basis','Standard skilled-work treatment when a specific role meets current requirements; 5/10.','salary_method','Midpoint of Tahatū current most-common Agricultural Technician annual pay range NZD 60,000-101,000, used as the closest direct technical proxy; 6/10.','entry_basis','Agricultural science/technology study plus practical animal-production or research experience provides the relevant technical route; 12/15.','entry_burden_basis','No universal statutory occupational registration applies to the generic Animal Science Technician scope; 5/5.'),'2026-08-11')
